draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 70 + 20 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 70 + 20 * Math.cos(t));
  ctx.stroke();

  // draw legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 - 20 + 15 * Math.sin(t + Math.PI/2), H/2 + 100 + 30 * Math.cos(t + Math.PI/2));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40);
  ctx.lineTo(W/2 + 20 + 15 * Math.sin(t + Math.PI/2), H/2 + 100 + 30 * Math.cos(t + Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
